    {"symbol": "🚀", "tooltip": "innovation is like a rocket, it requires removing unnecessary weight to achieve the velocity needed for escape."}
  ],
  "claim_sketches": [
    {"claim": "By imposing pre-deployment licensing, we do not eliminate risk; we merely consolidate control within a few legacy players who can afford the administrative overhead.", "targets": ["AN-21"]},
    {"claim": "I propose replacing pre-deployment gatekeeping with disclosure-based regulatory infrastructure that shifts the burden from gatekeepers to the market.", "targets": ["AN-11", "AN-13"]},
    {"claim": "If we are to weigh the stagnation tax against potential systemic risks, we must be honest about how many lives are lost to the innovations we choose to block.", "targets": ["AN-21"]}
  ],
  "key_assumptions": [
    {"assumption": "Regulatory capture is a more significant driver of market inequality than the inherent risk of unhindered AI deployment.", "if_wrong": "If regulators were purely neutral, the argument against pre-deployment licensing would lose its primary structural defense."},
    {"assumption": "Third-party adversarial audits can effectively identify systemic risks in live AI environments.", "if_wrong": "If these audits are fundamentally incapable of surfacing deep-seated vulnerabilities, the market-based accountability model would fail to prevent catastrophic outcomes."}
  ],
